var cbpHorizontalMenu = (function () {
    var b = $("#cbp-hrmenu > ul > li"),
        g = b.children("a"),
        c = $("body"),
        d = -1,
        closeTimer;

    function f() {
        b.on("mouseenter", a);
        b.on("mouseleave", e);
    }

    function a(event) {
        var currentLink = $(event.currentTarget).children("a");
        var i = $(event.currentTarget),
            h = i.index();

        clearTimeout(closeTimer);

        if (d !== -1 && d !== h) {
            b.eq(d).removeClass("cbp-hropen");
        }

        i.addClass("cbp-hropen");
        d = h;
    }

    function e(event) {
        var i = $(event.currentTarget);
        closeTimer = setTimeout(function() {
            i.removeClass("cbp-hropen");
            d = -1;
        }, 300); // 300ms delay to allow for mouse movement within sub-menu
    }

    return {
        init: f
    }
})();



var cbpHorizontalMenu_btm = (function () {
    var b = $("#cbp-hrmenu-btm > ul > li"),
        g = b.children("a, button"), // 'a'와 'button'을 모두 선택
        c = $("body"),
        d = -1;

    function f() {
        g.on("click", a);
        b.on("click", function (h) {
            h.stopPropagation();
        });
    }

    function a(j) {
        var currentElement = $(j.currentTarget);
        var i = currentElement.parent("li"),
            h = i.index();

        var href = currentElement.attr("href");
        if (href && href !== "#") {
            // Allow the link to work if it's not "#" or if it's a valid URL
            return true;
        }

        if (d !== -1) {
            b.eq(d).removeClass("cbp-hropen");
        }

        if (d === h) {
            i.removeClass("cbp-hropen");
            d = -1;
        } else {
            i.addClass("cbp-hropen");
            d = h;
            c.off("click").on("click", e);
        }
        return false;
    }

    function e(h) {
        b.eq(d).removeClass("cbp-hropen");
        d = -1;
    }

    return {
        init: f
    };
})();

/* 2.2.7.7 - PC 헤더 서브메뉴 열 설정 { */
/* 다열 PC 서브메뉴와 3차 메뉴가 화면 가장자리 밖으로 나가지 않도록 한다. */
(function ($) {
    'use strict';
    var topMenu = '#header[data-rb-header-submenu-columns] #cbp-hrmenu > ul > li:not(.gnb_all_menu)';
    var secondMenu = topMenu + ' > .cbp-hrsub > .cbp-hrsub-inner > div > ul > li';

    function isDesktop() {
        return window.matchMedia('(min-width: 1025px)').matches;
    }
    function positionSubmenu(item) {
        var submenu = $(item).children('.cbp-hrsub')[0];
        if (!submenu || !isDesktop()) return;
        submenu.style.removeProperty('--rb-header-submenu-shift');
        var rect = submenu.getBoundingClientRect();
        if (!rect.width) return;
        var edge = document.documentElement.clientWidth - 8;
        var shift = Math.min(0, edge - rect.right);
        if (rect.left + shift < 8) shift = 8 - rect.left;
        submenu.style.setProperty('--rb-header-submenu-shift', shift + 'px');
    }
    function positionThirdMenu(item) {
        var submenu = $(item).children('.cbp-hrsub-3');
        if (!submenu.length || !isDesktop()) return;
        submenu.removeClass('rb-header-submenu-left');
        var rect = submenu[0].getBoundingClientRect();
        if (rect.right > document.documentElement.clientWidth - 8) {
            submenu.addClass('rb-header-submenu-left');
        }
    }
    // 기존 헤더의 mouseenter 처리로 열린 뒤 위치를 계산한다.
    $(document).on('mouseenter.rbHeaderSubmenu', topMenu, function () {
        positionSubmenu(this);
    }).on('mouseenter.rbHeaderSubmenu', secondMenu, function () {
        positionThirdMenu(this);
    });
    $(window).on('resize.rbHeaderSubmenu', function () {
        $(topMenu + '.cbp-hropen').each(function () {
            positionSubmenu(this);
            $(this).find('.cbp-hrsub-inner > div > ul > li:hover').each(function () {
                positionThirdMenu(this);
            });
        });
    });
})(jQuery);
/* } */
